    public static Optional<TrackedEnemy> forNpcId(int id) {
        for (TrackedEnemy enemy : values()) {
            for (int npcId : enemy.npcIds) {
                if (npcId == id) {
                    return Optional.of(enemy);
                }
            }
        }
        return Optional.empty();
    }
